    .search-divider {
      width: 1px;
      height: 36px;
      background: var(--gray-200);
      flex-shrink: 0;
    }

    .btn-search {
      background: var(--yellow);
      color: var(--navy);
      font-weight: 700;
      font-size: 0.95rem;
      padding: 16px 28px;
      border-radius: var(--radius);
      white-space: nowrap;
      transition: background var(--transition), transform var(--transition);
      display: flex;
      align-items: center;
      gap: 6px;
      flex-shrink: 0;
    }

    .btn-search:hover {
      background: var(--yellow-dark);
      transform: translateY(-1px);
    }

    /* ── Autocomplete Dropdown ── */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 6px);
      left: 8px;
      right: auto;
      width: calc(100% - 8px);
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      z-index: 50;
      display: none;
      overflow: hidden;
      max-height: 320px;
      overflow-y: auto;
    }

    .autocomplete-dropdown.active { display: block; }

    .autocomplete-item {
      padding: 12px 18px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 0.925rem;
      color: var(--gray-800);
      transition: background var(--transition);
      border-bottom: 1px solid var(--gray-100);
    }

    .autocomplete-item:last-child { border-bottom: none; }
    .autocomplete-item:hover { background: var(--gray-50); }

    .autocomplete-item .suggestion-icon {
      width: 32px;
      height: 32px;
      background: var(--gray-100);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.85rem;
      flex-shrink: 0;
