    .section-header {
      text-align: center;
      margin-bottom: 56px;
    }

    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: var(--navy);
      background: rgba(27,20,100,0.06);
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 16px;
    }

    .section-header h2 {
      font-size: clamp(1.75rem, 3.5vw, 2.4rem);
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.5px;
      margin-bottom: 12px;
    }

    .section-header p {
      color: var(--gray-500);
      max-width: 560px;
      margin: 0 auto;
      font-size: 1.05rem;
    }

    /* ── Specialties Grid ── */
    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .specialty-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px 24px;
      text-align: center;
      cursor: pointer;
      transition: all var(--transition);
      position: relative;
    }

    .specialty-card:hover {
      border-color: var(--navy);
