    .step {
      text-align: center;
      position: relative;
      padding: 40px 28px;
    }

    .step-number {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--yellow);
      font-size: 1.4rem;
      font-weight: 800;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
