    /* ── Stats ── */
    .stats-bar {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .stat {
      text-align: center;
      padding: 36px 20px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      transition: transform var(--transition);
    }

    .stat:hover { transform: translateY(-2px); }

    .stat-value {
      font-size: clamp(1.8rem, 3.5vw, 2.4rem);
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.5px;
      line-height: 1.2;
      margin-bottom: 8px;
    }

    .stat-value .highlight {
      color: var(--green);
    }

    .stat-label {
      font-size: 0.9rem;
      color: var(--gray-500);
      font-weight: 500;
    }

    /* ── Testimonials ── */
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px;
      position: relative;
    }

    .testimonial .quote-mark {
      font-size: 3rem;
      line-height: 1;
      color: var(--yellow);
      font-weight: 800;
      font-family: Georgia, serif;
      margin-bottom: 12px;
    }

    .testimonial blockquote {
      font-size: 0.975rem;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: normal;
    }

    .testimonial .author {
      font-weight: 700;
      font-size: 0.9rem;
      color: var(--navy);
    }

    .testimonial .author-location {
      font-size: 0.8rem;
      color: var(--gray-400);
    }

    /* ── Mobile App Promo ── */
    .app-promo {
      background: var(--navy);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .app-promo::before {
      content: '';
