      letter-spacing: -0.5px;
    }

    .app-promo-content .subtitle {
      color: rgba(255,255,255,0.8);
      margin-bottom: 28px;
      font-size: 1.05rem;
      line-height: 1.6;
    }

    .app-features {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 14px;
      margin-bottom: 32px;
    }

    .app-feature {
      display: flex;
